<?php
/**
 * Tracy — com_content / article / default
 *
 * Starts from plugins/system/t4/themes/base/html/com_content/article/default.php. Everything the
 * base does (info block, icons, tags, pagination, urls, the guest teaser branch) is kept verbatim;
 * only three things change, and each is a design requirement the base cannot express:
 *
 *   1. The reading measure. design-spec.md §6 (article.html) caps it at 52ch — the value the
 *      fixture sets on .lead. The body is wrapped in .tracy-prose, which carries the cap.
 *   2. json_decode() is null-guarded (gotcha #64). The base reads $images->image_intro straight
 *      off a decode of a possibly-NULL column, which prints a Deprecated notice ON THE PAGE.
 *   3. The <pre>/<code> block in the prose is always dark (gotcha #67) — handled in
 *      scss/_overrides-content.scss, which is why the body carries its own class.
 *
 * No colour/size/space literal appears here; every visual decision is a class the partial styles.
 */

defined('_JEXEC') or die;

use Joomla\CMS\Factory;
use Joomla\CMS\HTML\HTMLHelper;
use Joomla\CMS\Language\Associations;
use Joomla\CMS\Language\Text;
use Joomla\CMS\Layout\FileLayout;
use Joomla\CMS\Layout\LayoutHelper;
use Joomla\CMS\Router\Route;
use Joomla\CMS\Uri\Uri;
use T4\Helper\J3J4;

if (!class_exists('ContentHelperRoute')) {
    if (version_compare(JVERSION, '4', 'ge')) {
        abstract class ContentHelperRoute extends \Joomla\Component\Content\Site\Helper\RouteHelper
        {
        };
    } else {
        JLoader::register('ContentHelperRoute', $com_path . '/helpers/route.php');
    }
}

HTMLHelper::addIncludePath(JPATH_COMPONENT . '/helpers');

// Create shortcuts to some parameters.
$params  = $this->item->params;

// Gotcha #64: these columns are NULL on a freshly created article. json_decode(null) emits a
// Deprecated notice that renders inside the page when display_errors is on.
$images  = json_decode($this->item->images ?: '{}');
$urls    = json_decode($this->item->urls ?: '{}');

$canEdit = $params->get('access-edit');
$user    = Factory::getUser();
$info    = $params->get('info_block_position', 0);

// Check if associations are implemented. If they are, define the parameter.
$assocParam = (Associations::isEnabled() && $params->get('show_associations'));

// Todo Not that elegant would be nice to group the params
$useDefList = ($params->get('show_modify_date') || $params->get('show_publish_date') || $params->get('show_create_date')
    || $params->get('show_hits') || $params->get('show_category') || $params->get('show_parent_category') || $params->get('show_author') || $assocParam);
?>
<div class="com-content-article item-page tracy-article<?php echo $this->pageclass_sfx; ?>" itemscope itemtype="https://schema.org/Article">
	<meta itemprop="inLanguage" content="<?php echo ($this->item->language === '*') ? Factory::getApplication()->get('language') : $this->item->language; ?>">

	<?php if ($this->params->get('show_page_heading')) : ?>
		<div class="page-header tracy-article__pagehead">
			<h1><?php echo $this->escape($this->params->get('page_heading')); ?></h1>
		</div>
	<?php endif; ?>

	<?php if (!empty($this->item->pagination) && $this->item->pagination && !$this->item->paginationposition && $this->item->paginationrelative) {
		echo $this->item->pagination;
	} ?>

	<?php if ($params->get('show_title') || $params->get('show_author')) : ?>
		<header class="page-header tracy-article__head">
			<?php if ($params->get('show_title')) : ?>
				<h2 class="tracy-article__title" itemprop="headline">
					<?php echo $this->escape($this->item->title); ?>
				</h2>
			<?php endif; ?>

			<?php // Content is generated by content plugin event "onContentAfterTitle" ?>
			<?php echo $this->item->event->afterDisplayTitle; ?>

			<?php if (J3J4::checkUnpublishedContent($this->item)) : ?>
				<span class="badge tracy-badge tracy-badge--warn"><?php echo Text::_('JUNPUBLISHED'); ?></span>
			<?php endif; ?>

			<?php
			$timePublishUp = $this->item->publish_up != null ? strtotime($this->item->publish_up) : '';
			if ($timePublishUp > strtotime(Factory::getDate())) : ?>
				<span class="badge tracy-badge tracy-badge--warn"><?php echo Text::_('JNOTPUBLISHEDYET'); ?></span>
			<?php endif; ?>

			<?php
			$timePublishDown = $this->item->publish_down != null ? strtotime($this->item->publish_down) : '';
			if ($this->item->publish_down && ($timePublishDown < strtotime(Factory::getDate())) && $this->item->publish_down != Factory::getDbo()->getNullDate()) : ?>
				<span class="badge tracy-badge tracy-badge--warn"><?php echo Text::_('JEXPIRED'); ?></span>
			<?php endif; ?>
		</header>
	<?php endif; ?>

	<div class="article-aside tracy-article__aside">
		<?php if ($useDefList && ($info == 0 || $info == 2)) : ?>
			<?php echo LayoutHelper::render('joomla.content.info_block', array('item' => $this->item, 'params' => $params, 'position' => 'above')); ?>
		<?php endif; ?>

		<?php if (!$this->print) : ?>
			<?php if ($canEdit || $params->get('show_print_icon') || $params->get('show_email_icon')) : ?>
				<?php echo LayoutHelper::render('joomla.content.icons', array('params' => $params, 'item' => $this->item, 'print' => false)); ?>
			<?php endif; ?>
		<?php else : ?>
			<?php if ($useDefList) : ?>
				<div id="pop-print" class="btn hidden-print">
					<?php echo HTMLHelper::_('icon.print_screen', $this->item, $params); ?>
				</div>
			<?php endif; ?>
		<?php endif; ?>
	</div>

	<?php if ($info == 0 && $params->get('show_tags', 1) && !empty($this->item->tags->itemTags)) : ?>
		<?php $this->item->tagLayout = new FileLayout('joomla.content.tags'); ?>
		<div class="tracy-tags"><?php echo $this->item->tagLayout->render($this->item->tags->itemTags); ?></div>
	<?php endif; ?>

	<?php // Content is generated by content plugin event "onContentBeforeDisplay" ?>
	<?php echo $this->item->event->beforeDisplayContent; ?>

	<?php if (isset($urls) && ((!empty($urls->urls_position) && ($urls->urls_position == '0')) || ($params->get('urls_position') == '0' && empty($urls->urls_position)))
		|| (empty($urls->urls_position) && (!$params->get('urls_position')))) : ?>
		<?php echo $this->loadTemplate('links'); ?>
	<?php endif; ?>

	<?php if ($params->get('access-view')) : ?>
		<?php // The lead image is deliberately OUTSIDE the measure — only prose is capped at 52ch. ?>
		<div class="tracy-article__media">
			<?php echo LayoutHelper::render('joomla.content.full_image', $this->item); ?>
		</div>

		<?php if (!empty($this->item->pagination) && $this->item->pagination && !$this->item->paginationposition && !$this->item->paginationrelative) :
			echo $this->item->pagination;
		endif; ?>

		<?php if (isset($this->item->toc)) : echo $this->item->toc; endif; ?>

		<div itemprop="articleBody" class="article-body tracy-prose">
			<?php echo $this->item->text; ?>
		</div>

		<?php if ($info == 1 || $info == 2) : ?>
			<?php if ($useDefList) : ?>
				<?php echo LayoutHelper::render('joomla.content.info_block', array('item' => $this->item, 'params' => $params, 'position' => 'below')); ?>
			<?php endif; ?>

			<?php if ($params->get('show_tags', 1) && !empty($this->item->tags->itemTags)) : ?>
				<?php $this->item->tagLayout = new FileLayout('joomla.content.tags'); ?>
				<div class="tracy-tags"><?php echo $this->item->tagLayout->render($this->item->tags->itemTags); ?></div>
			<?php endif; ?>
		<?php endif; ?>

		<?php
		if (!empty($this->item->pagination) && $this->item->pagination && $this->item->paginationposition && !$this->item->paginationrelative) :
			echo $this->item->pagination;
		endif;
		?>

		<?php if (isset($urls) && ((!empty($urls->urls_position) && ($urls->urls_position == '1')) || ($params->get('urls_position') == '1'))) : ?>
			<?php echo $this->loadTemplate('links'); ?>
		<?php endif; ?>

	<?php // Optional teaser intro text for guests ?>
	<?php elseif ($params->get('show_noauth') && $user->guest) : ?>
		<div class="tracy-article__media">
			<?php echo LayoutHelper::render('joomla.content.intro_image', $this->item); ?>
		</div>
		<div class="tracy-prose">
			<?php echo HTMLHelper::_('content.prepare', $this->item->introtext); ?>
		</div>

		<?php // Optional link to let them register to see the whole article. ?>
		<?php if ($params->get('show_readmore') && $this->item->fulltext != null) : ?>
			<?php
			$menu   = Factory::getApplication()->getMenu();
			$active = $menu->getActive();
			$itemId = $active ? $active->id : 0;
			$link   = new Uri(Route::_('index.php?option=com_users&view=login&Itemid=' . $itemId, false));
			$link->setVar('return', base64_encode(ContentHelperRoute::getArticleRoute($this->item->slug, $this->item->catid, $this->item->language)));
			$attribs = json_decode($this->item->attribs ?: '{}');
			?>
			<p class="com-content-article__readmore readmore tracy-article__readmore">
				<a href="<?php echo $link; ?>" class="register btn btn-primary">
					<?php
					if (empty($attribs->alternative_readmore)) :
						echo Text::_('COM_CONTENT_REGISTER_TO_READ_MORE');
					else :
						echo $attribs->alternative_readmore;
						if ($params->get('show_readmore_title', 0) != 0) :
							echo ' ' . HTMLHelper::_('string.truncate', $this->item->title, $params->get('readmore_limit'));
						endif;
					endif;
					?>
				</a>
			</p>
		<?php endif; ?>
	<?php endif; ?>

	<?php
	if (!empty($this->item->pagination) && $this->item->pagination && $this->item->paginationposition && $this->item->paginationrelative) :
		echo $this->item->pagination;
	endif;
	?>

	<?php // Content is generated by content plugin event "onContentAfterDisplay" ?>
	<?php echo $this->item->event->afterDisplayContent; ?>
</div>
